<script>
  import { onMount, tick } from 'svelte';
  import WindowControls from './WindowControls.svelte';
  import { pagesCapabilities, pagesWindow, pagesDocument, pagesDirty, pagesMenus, pagesText, pagesMargins, pagesDefaultToolbar, PAGES_TEMPLATES, PAGES_TOOLBAR_ITEMS } from './pages-model.js';
  import { createPagesNativeView, pagesParagraph } from './pages-native.js';
  import { pagesChartGeometry, pagesEstimatePages } from './pages-render.js';
  import './pages.css';
  import { createDocumentFonts } from './document-fonts.svelte.js';
  let { state: pagesState, profile, window: actualWindow = null, windowId: providedId = null, execute, registerView, available = true, active = true, controls = {}, getShared = name => controls.getShared?.(name), getFile = id => controls.getFile?.(id) } = $props();
  const windowId = $derived(providedId ?? actualWindow?.id), session = $derived(pagesWindow(pagesState, windowId)), document = $derived(session && pagesDocument(pagesState, session.documentId)), cap = $derived(pagesCapabilities(profile));
  const selected = $derived(document?.content.blocks.find(row => row.id === session?.selectedId)), paragraph = $derived(selected?.type === 'paragraph' ? selected : document?.content.blocks.find(row => row.id === session?.selection.blockId)), marks = $derived(paragraph?.runs[0]);
  const menus = $derived(pagesMenus({ state: pagesState, profile, windowId })), menu = $derived(menus.find(row => row.id === session?.menu)), pageGroups = $derived(document ? pagesEstimatePages(document.content) : []);
  const templates = $derived(PAGES_TEMPLATES.filter(row => session?.category === 'All Templates' || row.category === session?.category));
  let root = $state(null), facade, message = $state(''), browserFiles = $state([]), saveName = $state(''), exportFormat = $state('docx'), chartTitle = $state(''), chartData = $state(''), chartKind = $state('bar'), rows = $state(4), columns = $state(3);
  let originalState, originalWindow, originalProfile, originalId, originalSession, retired = false;
  const current = () => !retired && root?.isConnected === true && pagesState === originalState && actualWindow === originalWindow && profile === originalProfile && windowId === originalId && session === originalSession;
  async function command(suffix, payload = {}) {
    if (!current() || !available || !active) return;
    const response = await execute(`pages.${suffix}`, { windowId }, payload);
    if (!current()) return response;
    message = response?.status === 'applied' ? '' : response?.error?.message ?? 'The actual document operation is unavailable.';
    if (suffix === 'browser' && response?.status === 'applied') browserFiles = response.files ?? [];
    if (response?.status === 'applied' && ['text.replace', 'text.split', 'text.merge', 'paragraph.add', 'page.add', 'create', 'undo', 'redo', 'paste', 'cut'].includes(suffix)) { const originalDocument = document, selection = { ...session.selection }; await tick(); if (current() && document === originalDocument && JSON.stringify(session.selection) === JSON.stringify(selection)) facade?.selectRange(selection); }
    return response;
  }
  async function menuAction(item) { if (!current() || !item.enabled || !item.request) return; if (item.request.command.startsWith('app.') && session.menu) { await command('menu', { menu: null }); if (!current() || !available || !active) return; } const response = await execute(item.request.command, item.request.target, item.request.payload); if (current()) { message = response?.status === 'applied' ? '' : response?.error?.message ?? 'The actual menu action is unavailable.'; if (response?.status === 'applied' && session.menu) command('menu', { menu: null }); } }
  function selection(range) { if (!current() || !available || !active || JSON.stringify(range) === JSON.stringify(session.selection)) return; command('selection', range); }
  function textRange() { return facade?.captureSelection({ allowUnfocused: true }) ?? session.selection; }
  function format(style) { const range = textRange(); if (range?.blockId) command('text.format', { ...range, style }); }
  function align(value) { if (paragraph) command('paragraph.align', { blockId: paragraph.id, align: value }); }
  function paragraphOptions(block) { return { block, getRoot: () => root, fontCSS: (name, bold, italic) => documentFonts.css(name, bold, italic), fontRevision: documentFonts.revision, getSelection: () => session.selection, available: () => current() && available && active, execute: command, selection }; }
  function clipboard(event, suffix) { if (event.target.closest('[data-pages-paragraph]')) { event.preventDefault(); command(suffix); } }
  function keyboard(event) {
    if (!current() || !available || !active) return;
    const modifier = cap.windows ? event.ctrlKey : event.metaKey, key = event.key.toLowerCase();
    if (modifier) {
      const suffix = { n: 'window.new', o: 'open', s: 'save', p: 'print', w: 'window.close', z: event.shiftKey ? 'redo' : 'undo', y: 'redo' }[key];
      if (suffix) { event.preventDefault(); command(suffix, key === 's' && event.shiftKey ? { saveAs: true } : {}); }
      else if (['b', 'i', 'u'].includes(key) && paragraph) { event.preventDefault(); const property = { b: 'bold', i: 'italic', u: 'underline' }[key]; format({ [property]: !marks[property] }); }
      else if (['c', 'x', 'v'].includes(key) && event.target.closest('[data-pages-paragraph]')) { event.preventDefault(); command({ c: 'copy', x: 'cut', v: 'paste' }[key]); }
      else if (key === 'a' && event.target.closest('[data-pages-paragraph]')) { event.preventDefault(); if (facade?.selectAll()) selection(facade.captureSelection()); }
    } else if (event.key === 'Escape') { if (session.dialog) command('dialog', { dialog: null }); else if (session.popup) command('popup', { popup: null }); else command('menu', { menu: null }); }
    else if (event.key === 'Delete' && selected && !event.target.closest('input,textarea,[contenteditable="true"]')) { event.preventDefault(); command('object.delete', { blockId: selected.id }); }
    else if (['ArrowUp', 'ArrowDown'].includes(event.key) && selected && event.altKey && !event.target.closest('input,textarea,[contenteditable="true"]')) { event.preventDefault(); command('object.move', { blockId: selected.id, direction: event.key === 'ArrowUp' ? 'up' : 'down' }); }
  }
  async function drop(event) { event.preventDefault(); let fileId = event.dataTransfer?.getData('application/x-jesteros-file-id'); if (!fileId) { try { fileId = JSON.parse(event.dataTransfer?.getData('application/x-jesteros-file-ids') || '[]')[0]; } catch {} } if (typeof fileId === 'string' && fileId) await command(event.dataTransfer?.getData('application/x-jesteros-file-mime')?.startsWith('image/') ? 'image.insert' : 'open', { fileId }); }
  function saveSubmit(event) { event.preventDefault(); command(session.dialog === 'export' ? 'export' : 'save', session.dialog === 'export' ? { format: exportFormat, name: saveName } : { name: saveName, saveAs: true }); }
  function chartSubmit(event) { event.preventDefault(); const lines = chartData.split('\n').filter(line => line.trim()); const labels = [], values = []; for (const line of lines) { const separator = line.lastIndexOf('\t') >= 0 ? line.lastIndexOf('\t') : line.lastIndexOf(','); if (separator < 0 || !Number.isFinite(Number(line.slice(separator + 1)))) { message = 'Each chart row must be a label, a comma or tab, and a finite number.'; return; } labels.push(line.slice(0, separator).trim()); values.push(Number(line.slice(separator + 1))); } if (selected?.type === 'chart') command('chart.edit', { blockId: selected.id, kind: chartKind, title: chartTitle, labels, values }); }
  function selectObject(block) { command('object.select', { blockId: block.id }); }
  $effect(() => { const dialog = session?.dialog, title = document?.content.title; if (dialog === 'save' || dialog === 'export') saveName = `${title || 'Untitled'}.${dialog === 'export' ? exportFormat : 'docx'}`; });
  $effect(() => { if (selected?.type === 'chart' && session?.dialog === 'chart') { chartTitle = selected.title; chartKind = selected.kind; chartData = selected.labels.map((label, index) => `${label},${selected.values[index]}`).join('\n'); } });
  function toolbarDrag(event, id) { if (!current() || session.dialog !== 'toolbar') { event.preventDefault(); return; } event.dataTransfer.setData('application/x-jester-pages-toolbar', id); event.dataTransfer.effectAllowed = 'move'; }
  function toolbarDrop(event, before = null) { const id = event.dataTransfer.getData('application/x-jester-pages-toolbar'); if (!current() || session.dialog !== 'toolbar' || !PAGES_TOOLBAR_ITEMS.some(item => item.id === id) && id !== 'default') return; event.preventDefault(); event.stopPropagation(); event.dataTransfer.dropEffect = 'move'; if (id === before) return; if (id === 'default') { command('toolbar', pagesDefaultToolbar(profile)); return; } const items = session.toolbar.items.filter(item => item !== id), index = before ? items.indexOf(before) : items.length; items.splice(index < 0 ? items.length : index, 0, id); command('toolbar', { items }); }
  function toolbarToggle(id) { command('toolbar', { items: session.toolbar.items.includes(id) ? session.toolbar.items.filter(item => item !== id) : [...session.toolbar.items, id] }); }
  function toolbarMove(id, direction) { const items = [...session.toolbar.items], index = items.indexOf(id), next = index + direction; if (index < 0 || next < 0 || next >= items.length) return; [items[index], items[next]] = [items[next], items[index]]; command('toolbar', { items }); }
  function toolbarAway(event, id) { if (!current() || session.dialog !== 'toolbar' || event.dataTransfer.dropEffect !== 'none' || event.clientX <= 0 || event.clientY <= 0) return; const bar = root.querySelector('[data-pages-toolbar]'), box = bar?.getBoundingClientRect(); if (box && (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom)) command('toolbar', { items: session.toolbar.items.filter(item => item !== id) }); }
  onMount(() => { originalState = pagesState; originalWindow = actualWindow; originalProfile = profile; originalId = windowId; originalSession = session; facade = createPagesNativeView({ getRoot: () => root, getState: () => pagesState, getProfile: () => profile, getWindow: () => actualWindow, windowId, available: () => current() && available && active }); registerView?.(windowId, facade); return () => { retired = true; facade.destroy(); registerView?.(originalId, null, facade); }; });
  const documentFonts = createDocumentFonts({ getShared: name => getShared(name), getFile: id => getFile(id), getRoot: () => root, getOwner: () => [pagesState, profile, actualWindow, windowId, session] });
</script>

<section bind:this={root} class="pages-app" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} data-pages-window-id={windowId} data-profile={typeof profile === 'string' ? profile : profile.id} role="region" aria-label={cap.label} tabindex="0" onkeydown={keyboard} oncopy={event => clipboard(event, 'copy')} oncut={event => clipboard(event, 'cut')} onpaste={event => clipboard(event, 'paste')} ondragover={event => event.preventDefault()} ondrop={drop}>
  {#if session}
    <header class="pages-titlebar">
      {#if !cap.windows}<WindowControls active={active} onclose={() => command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen} zoomed={controls.zoomed}/>{/if}
      <span class="pages-title">{document && session.mode === 'editor' ? `${document.content.title}${pagesDirty(document) ? ' — Edited' : ''}` : session.mode === 'templates' ? 'Choose a Template' : 'Open a Document'}</span>
      {#if cap.windows}<span class="pages-local-label">Pages Local Equivalent</span>{/if}
    </header>
    {#if cap.windows}<nav class="pages-menu-strip" aria-label="Application menus">{#each menus as group}<button data-pages-control={`menu:${group.id}`} aria-expanded={session.menu === group.id} onclick={() => command('menu', { menu: session.menu === group.id ? null : group.id })}>{group.label}</button>{/each}</nav>{/if}
    {#if menu}<div class="pages-menu" role="menu" aria-label={menu.label}>{#each menu.children as item}<button role="menuitem" data-pages-control={`menuitem:${item.id}`} disabled={!item.enabled} onclick={() => menuAction(item)}><span>{item.checked ? '✓ ' : ''}{item.label}</span><kbd>{item.shortcut ?? ''}</kbd></button>{/each}</div>{/if}
    {#if cap.windows || cap.golden}<div class="pages-profile-disclosure">{cap.era}</div>{/if}
    <div class="pages-main" inert={!available || !active}>
      {#if session.mode === 'templates'}
        <div class="pages-chooser">
          <aside class="pages-template-categories" aria-label="Template categories">{#each ['All Templates', 'Basic', 'Reports', 'Letters', 'Resumes', 'Posters'] as category}<button class:selected={session.category === category} data-pages-control={`category:${category}`} onclick={() => command('templates', { category })}><span>{category === 'All Templates' ? '▦' : category === 'Basic' ? '▤' : category === 'Reports' ? '▥' : category === 'Letters' ? '✉' : '▧'}</span>{category}</button>{/each}<button class="pages-browse-link" data-pages-control="browse-documents" onclick={() => command('browser')}>Open a Document…</button></aside>
          <main class="pages-template-grid" data-pages-control="template-grid"><h1>Choose a Template</h1><p class="pages-category-heading">{session.category === 'All Templates' ? 'All Templates' : session.category}</p><div class="pages-template-cards">{#each templates as template}<button class="pages-template-card" class:selected={session.template === template.id} data-pages-control={`template:${template.id}`} onclick={() => command('templates', { template: template.id })} ondblclick={() => command('create', { template: template.id })}><div class="pages-template-preview" class:landscape={template.landscape} class:poster={template.id === 'poster'}>{#each template.paragraphs as [style, text]}<span class={`preview-${style.toLowerCase()}`}>{text}</span>{/each}{#if template.id !== 'blank' && template.id !== 'landscape'}<span class="pages-preview-lines"></span>{/if}</div><span class="pages-template-name">{template.name}</span></button>{/each}</div></main>
          <footer class="pages-chooser-footer"><span>Editable local templates · DOCX interchange</span><button data-pages-control="template-cancel" onclick={() => document ? command('document.switch', { documentId: document.id }) : command('window.close')}>Cancel</button><button class="pages-primary" data-pages-control="template-create" onclick={() => command('create', { template: session.template })}>{cap.classic ? 'Choose' : 'Create'}</button></footer>
        </div>
      {:else if session.mode === 'browser'}
        <div class="pages-browser"><header><button data-pages-control="browser-new" onclick={() => command('templates')}>New Document</button><strong>Documents</strong><input data-pages-control="browser-search" type="search" aria-label="Search virtual documents" placeholder="Search" value={session.browserQuery} onchange={event => command('browser', { query: event.currentTarget.value })}/><button data-pages-control="browser-refresh" onclick={() => command('browser')}>Refresh</button><button data-pages-control="browser-open" onclick={() => command('open')}>Open…</button></header>
          <h2>Open Documents</h2><div class="pages-document-cards">{#each pagesState.documents as row}<button data-pages-control={`document:${row.id}`} onclick={() => command('document.switch', { documentId: row.id })}><span class="pages-document-icon">▤</span><strong>{row.content.title}</strong><small>{pagesDirty(row) ? 'Edited — not saved' : 'Saved DOCX'}</small></button>{/each}{#if !pagesState.documents.length}<p>No documents are open. Choose New Document to begin.</p>{/if}</div>
          <h2>Virtual Files · Word documents</h2><div class="pages-browser-files">{#each browserFiles as file}<button data-pages-control={`file:${file.id}`} onclick={() => command('open', { fileId: file.id })}><span class="pages-document-icon">▤</span><strong>{file.name}</strong><small>{file.parentId} · revision {file.revision}</small></button>{/each}{#if !browserFiles.length}<p>No matching DOCX documents. Save a document or open one from the Root Files chooser.</p>{/if}</div><p class="pages-format-disclosure">Native .pages packages are not decoded. Use a genuine Word (.docx) export from Pages.</p>
        </div>
      {:else if document}
        {#if session.toolbar.visible || session.dialog === 'toolbar'}<div class="pages-toolbar" class:icons-only={session.toolbar.iconsOnly} class:customizing={session.dialog === 'toolbar'} data-pages-toolbar role="toolbar" aria-label="Pages document toolbar" ondragover={event => event.preventDefault()} ondrop={event => toolbarDrop(event)}>
          {#each session.toolbar.items as item (item)}<div class="pages-toolbar-item" class:pages-toolbar-inspectors={item === 'inspector'} data-toolbar-item={item} role="group" aria-label={PAGES_TOOLBAR_ITEMS.find(row => row.id === item)?.label} draggable={session.dialog === 'toolbar'} ondragstart={event => toolbarDrag(event, item)} ondragend={event => toolbarAway(event, item)} ondragover={event => event.preventDefault()} ondrop={event => toolbarDrop(event, item)}>
            {#if item === 'view'}<button data-pages-control="view-popup" class:pressed={session.popup === 'view'} title="View" onclick={() => command('popup', { popup: session.popup === 'view' ? null : 'view' })}><span class="tool-view">▤⌄</span>View</button>
            {:else if item === 'zoom'}<label class="pages-zoom"><select data-pages-control="zoom" aria-label="Document zoom" value={session.zoom} onchange={event => command('view', { zoom: Number(event.currentTarget.value) })}>{#each [.25, .5, .75, .85, 1, 1.25, 1.5, 2, 3, 4] as zoom}<option value={zoom}>{Math.round(zoom * 100)}%</option>{/each}</select><span>Zoom</span></label>
            {:else if item === 'page'}<button data-pages-control="add-page" title="Add Page" onclick={() => command('page.add')}><span>+</span>Add Page</button>
            {:else if item === 'insert'}<button data-pages-control="insert-popup" title="Insert" onclick={() => command('popup', { popup: session.popup === 'insert' ? null : 'insert' })}><span>¶⌄</span>Insert</button>
            {:else if item === 'table'}<button data-pages-control="table-popup" title="Table" onclick={() => command('popup', { popup: session.popup === 'table' ? null : 'table' })}><span class="tool-table">▦</span>Table</button>
            {:else if item === 'chart'}<button data-pages-control="chart-popup" title="Chart" onclick={() => command('popup', { popup: session.popup === 'chart' ? null : 'chart' })}><span class="tool-chart">▥</span>Chart</button>
            {:else if item === 'text'}<button data-pages-control="insert-text" title="Text" onclick={() => command('paragraph.add')}><span>Τ</span>Text</button>
            {:else if item === 'media'}<button data-pages-control="insert-media" title="Media" onclick={() => command('image.insert')}><span class="tool-media">▧</span>Media</button>
            {:else if item === 'share'}<button data-pages-control="share" title="Share" onclick={() => command('share')}><span>⇧</span>Share</button>
            {:else}<button data-pages-control="format-inspector" title="Format" class:pressed={session.inspector === 'format'} onclick={() => command('inspector', { panel: session.inspector === 'format' ? 'none' : 'format' })}><span>◩</span>Format</button><button data-pages-control="document-inspector" title="Document" class:pressed={session.inspector === 'document'} onclick={() => command('inspector', { panel: session.inspector === 'document' ? 'none' : 'document' })}><span>▤</span>Document</button>{/if}
          </div>{/each}
        </div>{/if}
        {#if session.popup}<div class={`pages-popover pages-popover-${session.popup}`} role="dialog" aria-label={`${session.popup} options`}>
          {#if session.popup === 'table'}<h3>Insert Table</h3><div class="pages-table-swatch">{#each Array(12) as _}<span></span>{/each}</div><label>Rows<input data-pages-control="table-rows" type="number" min="1" max="100" bind:value={rows}/></label><label>Columns<input data-pages-control="table-columns" type="number" min="1" max="12" bind:value={columns}/></label><button class="pages-primary" data-pages-control="table-insert" onclick={() => command('table.insert', { rows: Number(rows), columns: Number(columns) })}>Insert Table</button>
          {:else if session.popup === 'chart'}<h3>2D Charts</h3><div class="pages-chart-types">{#each ['bar', 'line', 'pie'] as kind}<button data-pages-control={`chart-insert:${kind}`} onclick={() => command('chart.insert', { kind })}><span>{kind === 'bar' ? '▥' : kind === 'line' ? '⌁' : '◔'}</span>{kind === 'bar' ? 'Column' : kind === 'line' ? 'Line' : 'Pie'}</button>{/each}</div><p>Editable data series · genuine DOCX charts</p>
          {:else if session.popup === 'insert'}<button data-pages-control="popup-text" onclick={() => command('paragraph.add')}>Text Paragraph</button><button data-pages-control="popup-image" onclick={() => command('image.insert')}>Choose Image…</button><button data-pages-control="popup-table" onclick={() => command('table.insert')}>Table</button><button data-pages-control="popup-chart" onclick={() => command('chart.insert')}>Chart</button>
          {:else}<button data-pages-control="popup-thumbnails" onclick={() => command('view', { thumbnails: !session.thumbnails })}>{session.thumbnails ? '✓ ' : ''}Page Thumbnails</button><button data-pages-control="popup-browser" onclick={() => command('browser')}>Document Browser</button><button data-pages-control="popup-actual-size" onclick={() => command('view', { zoom: 1 })}>Actual Size</button>{/if}
          <button class="pages-popover-close" data-pages-control="popover-close" aria-label="Close popover" onclick={() => command('popup', { popup: null })}>×</button>
        </div>{/if}
        <div class="pages-editor-workspace">
          {#if session.thumbnails}<aside class="pages-thumbnails" aria-label="Page thumbnails">{#each pageGroups as group, index}<button class:page-selected={group.includes(session.pageAnchor)} data-pages-control={`page:${index + 1}`} onclick={() => command('page.select', { blockId: group[0], focus: true })}><span class="pages-thumbnail-paper">{#each group.slice(0, 8) as id}<i></i>{/each}</span><span>{index + 1}</span></button>{/each}<small>Screen-flow pages; PDF repaginates with embedded font.</small></aside>{/if}
          <main class="pages-canvas" data-pages-control="canvas" tabindex="0" aria-label="Editable document pages">
            <div class="pages-document-tabs">{#each pagesState.documents as row}<button class:selected={row.id === document.id} data-pages-control={`tab:${row.id}`} onclick={() => command('document.switch', { documentId: row.id })}>{row.content.title}{pagesDirty(row) ? ' •' : ''}</button>{/each}<button data-pages-control="new-document" aria-label="New document" onclick={() => command('window.new')}>+</button></div>
            <div class="pages-paper-stack" style:zoom={session.zoom}>
              {#each pageGroups as group, pageIndex}<article class="pages-paper" style:width={`${document.content.page.width}px`} style:min-height={`${document.content.page.height}px`} style:padding={`${['top', 'right', 'bottom', 'left'].map(side => `${pagesMargins(document.content.page)[side]}px`).join(' ')}`} data-pages-control={`page-surface:${pageIndex + 1}`} tabindex="-1" aria-label={`Document page ${pageIndex + 1}`} onpointerdown={event => { if (!event.target.closest('[data-pages-paragraph],.pages-object')) command('page.select', { blockId: group[0] }); }}>
                {#each group as id (id)}{@const item = document.content.blocks.find(row => row.id === id)}
                  {#if item?.type === 'paragraph'}<div class="pages-paragraph" class:object-selected={session.selectedId === item.id} style:text-align={item.align} data-pages-paragraph={item.id} data-pages-control={`paragraph:${item.id}`} contenteditable={available && active ? 'true' : 'false'} role="textbox" aria-label={`${item.style} paragraph`} aria-multiline="true" spellcheck="true" use:pagesParagraph={paragraphOptions(item)}></div>
                  {:else if item?.type === 'table'}<div class="pages-object pages-table-object" class:object-selected={selected?.id === item.id} tabindex="0" role="group" aria-label="Document table" data-pages-control={`object:${item.id}`} onfocus={() => selectObject(item)}><table><tbody>{#each item.rows as cells, row}<tr>{#each cells as cell, column}<td><input data-pages-control={`cell:${item.id}:${row}:${column}`} aria-label={`Table row ${row + 1}, column ${column + 1}`} value={cell.text} onfocus={() => selectObject(item)} onchange={event => command('table.cell', { blockId: item.id, row, column, text: event.currentTarget.value })}/></td>{/each}</tr>{/each}</tbody></table></div>
                  {:else if item?.type === 'image'}<button class="pages-object pages-image-object" class:object-selected={selected?.id === item.id} data-pages-control={`object:${item.id}`} onclick={() => selectObject(item)} aria-label={`Select image: ${item.alt}`}><img src={item.content} alt={item.alt} style:width={`${item.width}px`} style:height={`${item.height}px`}/></button>
                  {:else if item?.type === 'chart'}{@const geometry = pagesChartGeometry(item)}<button class="pages-object pages-chart-object" class:object-selected={selected?.id === item.id} data-pages-control={`object:${item.id}`} onclick={() => selectObject(item)} ondblclick={() => { selectObject(item); command('dialog', { dialog: 'chart' }); }} aria-label={`Select ${item.kind} chart: ${item.title}`}><strong>{item.title}</strong><svg viewBox={`0 0 ${geometry.width} ${geometry.height}`} role="img" aria-label={`${item.title}: ${item.labels.map((label, index) => `${label} ${item.values[index]}`).join(', ')}`}>
                    {#each geometry.marks as mark}{#if mark.type === 'rect'}<rect x={mark.x} y={mark.y} width={mark.width} height={mark.height} fill={mark.color}/>{:else if mark.type === 'line'}<line x1={mark.x1} y1={mark.y1} x2={mark.x2} y2={mark.y2} stroke={mark.color} stroke-width="2"/>{:else if mark.type === 'circle'}<circle cx={mark.x} cy={mark.y} r={mark.radius} fill={mark.color}/>{:else}<polygon points={mark.points.map(point => point.join(',')).join(' ')} fill={mark.color}/>{/if}{/each}
                    {#each geometry.labels as label}<text x={label.x} y={label.y} text-anchor={label.center ? 'middle' : 'start'} fill={label.color} font-size="10">{label.text}</text>{/each}</svg></button>{/if}
                {/each}<span class="pages-page-number">{pageIndex + 1}</span>
              </article>{/each}
            </div>
          </main>
          {#if session.inspector !== 'none'}<aside class="pages-inspector" aria-label={`${session.inspector} inspector`}>
            <header><strong>{session.inspector === 'document' ? 'Document' : selected?.type === 'table' ? 'Table' : selected?.type === 'image' ? 'Image' : selected?.type === 'chart' ? 'Chart' : 'Text'}</strong><button data-pages-control="inspector-close" aria-label="Close inspector" onclick={() => command('inspector', { panel: 'none' })}>×</button></header>
            {#if session.inspector === 'document'}
              <div class="pages-inspector-tabs"><span class="selected">Document</span></div>
              <fieldset><legend>Document</legend><label>Title<input data-pages-control="document-title" maxlength="128" value={document.content.title} onchange={event => command('document.rename', { title: event.currentTarget.value })}/></label></fieldset>
              <fieldset><legend>Paper Size</legend>
                <select data-pages-control="paper-size" aria-label="Paper size" value={document.content.page.width === 595.28 ? 'a4' : document.content.page.width > document.content.page.height ? 'landscape' : 'letter'} onchange={event => command('page', { width: event.currentTarget.value === 'a4' ? 595.28 : event.currentTarget.value === 'landscape' ? 792 : 612, height: event.currentTarget.value === 'a4' ? 841.89 : event.currentTarget.value === 'landscape' ? 612 : 792, margin: document.content.page.margin })}><option value="letter">US Letter</option><option value="a4">A4</option><option value="landscape">US Letter Landscape</option></select>
                {#each ['width', 'height'] as property}<label>{property === 'width' ? 'Width (pt)' : 'Height (pt)'}<input data-pages-control={`paper:${property}`} type="number" min="144" max="1440" step="1" value={document.content.page[property]} onchange={event => command('page', { ...document.content.page, [property]: Number(event.currentTarget.value) })}/></label>{/each}
              </fieldset>
              <fieldset><legend>Document Margins (pt)</legend>{#each ['top', 'right', 'bottom', 'left'] as side}<label>{side}<input data-pages-control={`margin:${side}`} type="number" min="0" max="360" step="1" value={pagesMargins(document.content.page)[side]} onchange={event => command('page', { ...document.content.page, margin: { ...pagesMargins(document.content.page), [side]: Number(event.currentTarget.value) } })}/></label>{/each}</fieldset>
              <fieldset><legend>Interchange</legend><p>Save and open genuine Word (.docx) documents. Native Apple .pages IWA packages are unavailable.</p><p>PDF embeds Liberation Sans; named fonts are substituted and bold/italic are synthesized. Image alternative descriptions are local only in DOCX interchange.</p></fieldset>
            {:else if selected?.type === 'table'}<div class="pages-inspector-tabs"><span class="selected">Table</span><span>Cell</span></div><fieldset><legend>Table Size</legend><label>Rows<input data-pages-control="inspector-table-rows" type="number" min="1" max="100" value={selected.rows.length} onchange={event => command('table.resize', { blockId: selected.id, rows: Number(event.currentTarget.value), columns: selected.rows[0].length })}/></label><label>Columns<input data-pages-control="inspector-table-columns" type="number" min="1" max="12" value={selected.rows[0].length} onchange={event => command('table.resize', { blockId: selected.id, rows: selected.rows.length, columns: Number(event.currentTarget.value) })}/></label><p>Edit cells directly on the page. Resizing retains cells that remain inside the new dimensions; Undo restores removed cells.</p></fieldset>
            {:else if selected?.type === 'image'}<div class="pages-inspector-tabs"><span class="selected">Image</span><span>Arrange</span></div><fieldset><legend>Size</legend>{#each ['width', 'height'] as dimension}<label>{dimension}<input data-pages-control={`image:${dimension}`} type="number" min="1" max="1200" value={selected[dimension]} onchange={event => command('image.size', { blockId: selected.id, [dimension]: Number(event.currentTarget.value) })}/></label>{/each}<label>Description<input data-pages-control="image-alt" maxlength="256" value={selected.alt} onchange={event => command('image.size', { blockId: selected.id, alt: event.currentTarget.value })}/></label><p>Real embedded PNG/JPEG bytes. Inline with document flow.</p></fieldset>
            {:else if selected?.type === 'chart'}<div class="pages-inspector-tabs"><span class="selected">Chart</span><span>Series</span></div><fieldset><legend>Chart</legend><p>{selected.kind === 'bar' ? 'Column' : selected.kind === 'line' ? 'Line' : 'Pie'} chart · {selected.labels.length} values</p><button data-pages-control="chart-edit-data" onclick={() => command('dialog', { dialog: 'chart' })}>Edit Chart Data…</button><p>Data-backed chart; DOCX contains real DrawingML caches. PDF contains actual plotted vector geometry.</p></fieldset>
            {:else if paragraph}<div class="pages-inspector-tabs"><span class="selected">Style &amp; Layout</span></div><fieldset><legend>Paragraph Style</legend><select data-pages-control="paragraph-style" aria-label="Paragraph style" value={paragraph.style} onchange={event => command('paragraph.style', { blockId: paragraph.id, style: event.currentTarget.value })}>{#each ['Body', 'Title', 'Subtitle', 'Heading', 'Caption'] as style}<option>{style}</option>{/each}</select></fieldset><fieldset><legend>Font</legend><select data-pages-control="font" aria-label="Font family" value={marks.font} onchange={event => format({ font: event.currentTarget.value })}>{#each documentFonts.choices(marks.font) as font}<option value={font} disabled={!documentFonts.has(font)}>{font}{!documentFonts.has(font) ? ' (unavailable)' : ''}</option>{/each}</select><div class="pages-text-controls"><button data-pages-control="bold" class:pressed={marks.bold} aria-pressed={marks.bold} onclick={() => format({ bold: !marks.bold })}><b>B</b></button><button data-pages-control="italic" class:pressed={marks.italic} aria-pressed={marks.italic} onclick={() => format({ italic: !marks.italic })}><i>I</i></button><button data-pages-control="underline" class:pressed={marks.underline} aria-pressed={marks.underline} onclick={() => format({ underline: !marks.underline })}><u>U</u></button><input data-pages-control="font-size" aria-label="Font size" type="number" min="6" max="144" step="0.5" value={marks.size} onchange={event => format({ size: Number(event.currentTarget.value) })}/></div><label>Text Color<input data-pages-control="text-color" type="color" value={marks.color} onchange={event => format({ color: event.currentTarget.value })}/></label></fieldset><fieldset><legend>Alignment</legend><div class="pages-alignment">{#each ['left', 'center', 'right', 'justify'] as alignment}<button data-pages-control={`align:${alignment}`} aria-label={`Align ${alignment}`} class:pressed={paragraph.align === alignment} onclick={() => align(alignment)}>{alignment === 'left' ? '☰' : alignment === 'center' ? '≡' : alignment === 'right' ? '☷' : '▤'}</button>{/each}</div><p>Select text to format a range. With an insertion point, formatting applies to the paragraph.</p></fieldset>{:else}<p class="pages-inspector-empty">Select text, a table, image, or chart to format it.</p>{/if}
            {#if selected && selected.type !== 'paragraph'}<fieldset><legend>Arrange · Inline Objects</legend><div class="pages-arrange-buttons"><button data-pages-control="object-up" onclick={() => command('object.move', { blockId: selected.id, direction: 'up' })}>Earlier</button><button data-pages-control="object-down" onclick={() => command('object.move', { blockId: selected.id, direction: 'down' })}>Later</button></div><button data-pages-control="object-delete" onclick={() => command('object.delete', { blockId: selected.id })}>Delete Object</button></fieldset>{/if}
          </aside>{/if}
        </div>
      {/if}
      {#if session.dialog}<div class="pages-sheet-backdrop" class:toolbar-customizer={session.dialog === 'toolbar'}><section class="pages-sheet" role="dialog" aria-modal="true" aria-label={session.dialog === 'save' ? 'Save document' : session.dialog === 'export' ? 'Export document' : session.dialog === 'close' ? 'Save changes' : session.dialog === 'chart' ? 'Edit chart data' : session.dialog === 'toolbar' ? 'Customize Toolbar' : 'Pages Help'}>
        {#if session.dialog === 'save' || session.dialog === 'export'}<form onsubmit={saveSubmit}><h2>{session.dialog === 'save' ? 'Save Your Document' : 'Export Your Document'}</h2>{#if session.dialog === 'export'}<label>Format<select data-pages-control="export-format" bind:value={exportFormat}><option value="docx">Word (.docx)</option><option value="pdf">PDF</option></select></label>{/if}<label>Save As<input data-pages-control="save-name" maxlength="128" bind:value={saveName} required/></label><label>Where<select data-pages-control="save-location" aria-label="Virtual save location"><option>Documents — virtual Files</option></select></label><p>Native .pages packages are unavailable. DOCX contains real rich text, images, tables, and charts. PDF uses bundled font substitution.</p><footer><button type="button" data-pages-control="save-cancel" onclick={() => command('dialog', { dialog: null })}>Cancel</button><button class="pages-primary" data-pages-control="save-confirm">{session.dialog === 'save' ? 'Save' : 'Export'}</button></footer></form>
        {:else if session.dialog === 'close'}<h2>Do you want to save the changes made to “{document?.content.title}”?</h2><p>Your unsaved changes will be lost if you don’t save them.</p><footer><button data-pages-control="close-discard" onclick={() => command('window.close', { discard: true })}>Don’t Save</button><span></span><button data-pages-control="close-cancel" onclick={() => command('dialog', { dialog: null })}>Cancel</button><button class="pages-primary" data-pages-control="close-save" onclick={() => command('save')}>Save…</button></footer>
        {:else if session.dialog === 'chart'}<form onsubmit={chartSubmit}><h2>Edit Chart Data</h2><label>Title<input data-pages-control="chart-title" maxlength="256" bind:value={chartTitle}/></label><label>Type<select data-pages-control="chart-kind" bind:value={chartKind}><option value="bar">Column</option><option value="line">Line</option><option value="pie">Pie</option></select></label><label>Data (label, value)<textarea data-pages-control="chart-data" rows="8" bind:value={chartData}></textarea></label><p>One label and numeric value per line. Pie values must be nonnegative with a positive total.</p><footer><button type="button" data-pages-control="chart-cancel" onclick={() => command('dialog', { dialog: null })}>Cancel</button><button class="pages-primary" data-pages-control="chart-confirm">Update Chart</button></footer></form>
        {:else if session.dialog === 'toolbar'}<h2>Customize Toolbar</h2><p>Drag controls to the actual toolbar, drag them away to remove, or reorder them. Format and Document move together. Click a palette control to add or remove it.</p><div class="pages-toolbar-palette">{#each PAGES_TOOLBAR_ITEMS as item}<button class:pressed={session.toolbar.items.includes(item.id)} draggable="true" data-pages-control={`toolbar-palette:${item.id}`} ondragstart={event => toolbarDrag(event, item.id)} onclick={() => toolbarToggle(item.id)}><span>{item.icon}</span>{item.label}</button>{/each}</div><div class="pages-toolbar-order" aria-label="Configured toolbar order">{#each session.toolbar.items as id, index}<div><span>{PAGES_TOOLBAR_ITEMS.find(item => item.id === id)?.label}</span><button data-pages-control={`toolbar-earlier:${id}`} disabled={index === 0} aria-label={`Move ${id} earlier`} onclick={() => toolbarMove(id, -1)}>←</button><button data-pages-control={`toolbar-later:${id}`} disabled={index === session.toolbar.items.length - 1} aria-label={`Move ${id} later`} onclick={() => toolbarMove(id, 1)}>→</button></div>{/each}</div><label>Show<select data-pages-control="toolbar-labels" value={session.toolbar.iconsOnly ? 'icons' : 'labels'} onchange={event => command('toolbar', { iconsOnly: event.currentTarget.value === 'icons' })}><option value="labels">Icon and Text</option><option value="icons">Icon Only</option></select></label><button draggable="true" data-pages-control="toolbar-default" ondragstart={event => toolbarDrag(event, 'default')} onclick={() => command('toolbar', pagesDefaultToolbar(profile))}>Default Set — drag to restore</button><footer><button class="pages-primary" data-pages-control="toolbar-done" onclick={() => command('dialog', { dialog: null })}>Done</button></footer>
        {:else}<h2>{cap.label}</h2><p>Installed font families are the original shared Font Book/Font Library sources, not proprietary Apple or Microsoft fonts. Enablement and source changes update this mounted document. Unavailable authored family names remain literal and use a safe browser rendering fallback; existing export font-embedding scopes are unchanged.</p><p>{cap.era}. This is a local simulated document editor, not a hosted Apple service.</p><p>Create a template, edit styled text, add real image Files, editable tables, and data-backed charts. Save/open actual DOCX; export actual PDFs. Print and Share open the Root native destinations. No remote collaboration or external delivery is claimed.</p><p>Use {cap.windows ? 'Ctrl' : 'Command'}-N/O/S/P/Z, Shift-{cap.windows ? 'Ctrl' : 'Command'}-Z, and {cap.windows ? 'Ctrl' : 'Command'}-B/I/U. Objects can be reordered using the Arrange inspector or Alt-arrow keys.</p><p>Native .pages IWA documents are unavailable. Screen pagination approximates document flow; exported PDF repaginates with embedded Liberation Sans and synthesized emphasis.</p><footer><button class="pages-primary" data-pages-control="help-close" onclick={() => command('dialog', { dialog: null })}>Done</button></footer>{/if}
      </section></div>{/if}
    </div>
    <footer class="pages-status" aria-live="polite"><span>{documentFonts.error || message || session.status || (document && session.mode === 'editor' ? `${document.content.blocks.filter(row => row.type === 'paragraph').reduce((sum, row) => sum + (pagesText(row).trim().match(/\S+/gu)?.length ?? 0), 0)} words · ${pagesDirty(document) ? 'Edited' : 'Saved'} · DOCX` : 'Choose a template or open a Word document.')}</span>{#if document && session.mode === 'editor'}<button data-pages-control="status-save" onclick={() => command('save')}>Save…</button>{/if}</footer>
  {:else}<p role="alert">The original canonical Pages session is unavailable.</p>{/if}
</section>
